#include <stdio.h>
#include <string.h>

int days_in_month[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

int is_valid_date(char *date) {
    int day, month, year;
    sscanf(date, "%d-%d-%d", &day, &month, &year);
    if (month < 1 || month > 12) return 0;
    if (day < 1 || day > days_in_month[month-1]) return 0;
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("INVALID\n");
        return 1;
    }
    char *date = argv[1];
    if (strlen(date) != 10) {
        printf("INVALID\n");
        return 1;
    }
    if (date[4] != '-' || date[7] != '-') {
        printf("INVALID\n");
        return 1;
    }
    int day, month, year;
    sscanf(date, "%d-%d-%d", &day, &month, &year);
    if (is_valid_date(date)) {
        printf("VALID\n");
    } else {
        printf("INVALID\n");
    }
    return 0;
}
